// Loop over input items and add a new field called 'myNewField' to the JSON of each one

const employees = $input.all().map(item => item.json);

const department = employees[0]?.department ?? 'Unknown';

const salaries = employees.map(employee => Number(employee.salary));
const totalSalary = salaries.reduce((sum, salary) => sum + salary, 0);
const averageSalary = salaries.length
  ? totalSalary / salaries.length
  : 0;

const employeeLines = employees.map((employee, index) =>
  `${index + 1}. ${employee.firstName} ${employee.lastName} — $${Number(employee.salary).toLocaleString('en-US')}`
);

const report = [
  'EmployeeHub — Department Report',
  `Department: ${department}`,
  `Total employees: ${employees.length}`,
  `Total salary: $${totalSalary.toLocaleString('en-US')}`,
  `Average salary: $${averageSalary.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })}`,
  '',
  'Employees:',
  ...employeeLines
].join('\n');

return [
  {
    json: {
      department,
      employeeCount: employees.length,
      totalSalary,
      averageSalary,
      employees,
      report
    }
  }
];

